import OpenAI from 'openai'

const openai = new OpenAI({ apiKey: uni.getStorageSync('apiKey') })

async function streamChat(question, aiMsg) {
  // 1. 如果启用RAG，先检索知识库 (向量相似度搜索)
  let context = ''
  if (agent.value.ragEnabled && agent.value.knowledgeBaseId) {
    const vec = await getEmbedding(question)
    const results = await searchKB(agent.value.knowledgeBaseId, vec)
    context = results.map(r => r.content).join('\n')
  }

  // 2. 构建messages (系统提示词 + RAG上下文 + 对话历史)
  const sysPrompt = context
    ? agent.value.systemPrompt + '\n参考信息:\n' + context
    : agent.value.systemPrompt

  const msgHistory = [
    { role: 'system', content: sysPrompt },
    ...messages.value.map(m => ({ role: m.role, content: m.content }))
  ]

  // 3. 添加函数调用工具 (Function Call)
  const tools = agent.value.tools?.map(t => getToolSchema(t)).filter(Boolean) || []

  const res = await openai.chat.completions.create({
    model: 'gpt-4o',
    messages: msgHistory,
    tools: tools.length ? tools : undefined,
    stream: true
  })

  // 4. 流式输出 (逐字追加，Vue自动更新视图)
  for await (const chunk of res) {
    const content = chunk.choices[0]?.delta?.content || ''
    aiMsg.content += content
  }
}

// 定义可用的函数工具 (Function Call Schema)
const toolSchemas = {
  web_search: {
    type: 'function',
    function: {
      name: 'webSearch',
      description: '搜索互联网获取最新信息',
      parameters: {
        type: 'object',
        properties: { query: { type: 'string' } },
        required: ['query']
      }
    }
  },
  mindmap: {
    type: 'function',
    function: {
      name: 'generateMindmap',
      description: '根据主题生成思维导图结构',
      parameters: {
        type: 'object',
        properties: { topic: { type: 'string' } },
        required: ['topic']
      }
    }
  }
}

// 处理AI的函数调用请求 (Function Call)
async function handleToolCalls(toolCalls) {
  const results = []
  for (const tc of toolCalls) {
    const fn = tc.function.name
    const args = JSON.parse(tc.function.arguments)
    let result
    if (fn === 'webSearch') {
      const res = await fetch('https://api.search.com?q=' + args.query)
      result = await res.json()
    } else if (fn === 'generateMindmap') {
      result = await generateMindmapData(args.topic)
    }
    results.push({ tool_call_id: tc.id, role: 'tool', content: JSON.stringify(result) })
  }
  return results
}

// 在对话中使用函数调用 (当AI返回tool_calls时执行函数并返回结果)
async function chatWithTools(messages, toolSchemas) {
  const res = await openai.chat.completions.create({
    model: 'gpt-4o', messages,
    tools: toolSchemas
  })

  if (res.choices[0].message.tool_calls) {
    // AI要求调用函数，执行并返回结果 (Function Call循环)
    const toolResults = await handleToolCalls(res.choices[0].message.tool_calls)
    messages.push(res.choices[0].message)
    messages.push(...toolResults)
    return await openai.chat.completions.create({ model: 'gpt-4o', messages })
  }
  return res
}

import Database from 'better-sqlite3'
import { vec } from 'sqlite-vec'
import OpenAI from 'openai'

const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY })
const db = new Database('knowledge.db')
vec.load(db)

// 初始化表结构
db.exec('
  CREATE TABLE IF NOT EXISTS knowledge_bases (id INTEGER PRIMARY KEY, name TEXT, userId INTEGER);
  CREATE TABLE IF NOT EXISTS documents (id INTEGER PRIMARY KEY, kbId INTEGER, name TEXT, status TEXT);
  CREATE TABLE IF NOT EXISTS text_chunks (id INTEGER PRIMARY KEY, docId INTEGER, content TEXT);
  CREATE VIRTUAL TABLE IF NOT EXISTS vec_chunks USING vec0(chunk_embedding float[1536]);
')

// 1. 获取向量 (调用Embedding API)
async function getEmbedding(text) {
  const res = await openai.embeddings.create({
    model: 'text-embedding-3-small',
    input: text.substring(0, 8000)
  })
  return res.data[0].embedding
}

// 2. 处理文档 (分割 -> 向量化 -> 存入sqlite-vec)
async function processDocument(docId, text) {
  const chunks = text.split(/\n\n+/).filter(p => p.length > 50)
  const insertChunk = db.prepare('INSERT INTO text_chunks (docId, content) VALUES (?, ?)')
  const insertVec = db.prepare('INSERT INTO vec_chunks (rowid, chunk_embedding) VALUES (?, ?)')
  for (const chunk of chunks) {
    const { lastInsertRowid } = insertChunk.run(docId, chunk)
    const vec = await getEmbedding(chunk)
    insertVec.run(lastInsertRowid, new Float32Array(vec))
  }
  db.prepare('UPDATE documents SET status = ? WHERE id = ?').run('done', docId)
}

// 3. 相似度检索 (余弦相似度，返回最相关的K个片段)
async function searchKB(kbId, query, limit = 3) {
  const vec = await getEmbedding(query)
  return db.prepare('SELECT tc.content, v.distance FROM vec_chunks v JOIN text_chunks tc ON tc.id = v.rowid JOIN documents d ON d.id = tc.docId WHERE d.kbId = ? AND v.chunk_embedding MATCH ? ORDER BY v.distance LIMIT ?').all(kbId, new Float32Array(vec), limit)
}

